CREATE OR REPLACE FUNCTION order_enqueue_order_shipped() RETURNS trigger AS $$
BEGIN
  -- Enqueues a message of OrderShipped after a write to order (D80).
  IF TG_OP = 'UPDATE' AND NOT (OLD.note IS DISTINCT FROM NEW.note) THEN
    RETURN NULL;
  END IF;
  IF NEW.note IS NOT NULL THEN
    INSERT INTO order_shipped_queue (order_id, note) VALUES (NEW.id, NEW.note)
      ON CONFLICT (order_id) WHERE state = 'ready' DO UPDATE SET note = excluded.note, due_at = excluded.due_at, attempts = 0, last_error = NULL, updated_at = now();
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql
